async function setupCrashHandler() {
  if (os.platform() !== "win32") return;
  const { getBlitzCore } = require("./native-utils");
  const crash_dir = path.join(app.getPath("temp"), "blitz");
  try {
    await fse.mkdirp(crash_dir);
  } catch (err) {}
  const param = {
    dir: crash_dir,
    fulldump: true,
    params: {
      process_type: "browser",
      _version: app.getVersion(),
      _productName: "Blitz",
      ver: process.versions.electron,
    },
  };
  getBlitzCore().InitCrashHandler(param);
}

module.exports = {
  setupCrashHandler,
};

const getUserProfile = async () => {
  let userProfile = null;
  try {
    const data = await get("USER_PROFILE");
    const parsed = JSON.parse(data);
    if (parsed && parsed.expiresAt && parsed.expiresAt > Date.now()) {
      userProfile = {
        ...parsed,
        version: parsed.version ?? LEGACY_USER_PROFILE_VERSION,
      };

      if (parsed.version == null) {
        try {
          await write("USER_PROFILE", JSON.stringify(userProfile));
        } catch {
          // The valid cached profile can still be used if its migration fails.
        }
      }

      return userProfile;
    }
  } catch {
    // falls through
  }
  if (!userProfile) {
    try {
      const machineId = getMachineID();
      const hash = crypto.createHash("sha256").update(machineId).digest("hex");
      const request = await fetch(
        `https://data.v2.iesdev.com/api/v1/query_objects/prod/bi/machine_segment?id=${hash}`
      );
      const data = await request.json();
      const profile = data?.data?.[0];
      if (profile?.segment != null) {
        userProfile = {
          type: profile.segment,
          version: profile.version ?? LEGACY_USER_PROFILE_VERSION,
          expiresAt: Date.now() + 24 * 60 * 60 * 1000,
        };
        await write("USER_PROFILE", JSON.stringify(userProfile));
        return userProfile;
      }
    } catch {
      // falls through
    }
  }
};

